# POST /api/sheets/{sheetId}/people/{personId}/patrons — name another person on the sheet as the
# person's patron (body: {user, patronId}). Refused (400), storing nothing, when either is not on the
# sheet, when the patron is the person themselves, or when they are already one of their patrons.
# A stored patron is recorded in the audit file as PATRON_ADDED.
validate:
  class: net.officefloor.hq.app.person.ValidatePatron
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.person.AddPatron
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPatronAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Names the patron as the person's, refusing themselves, someone not on the sheet, or a patron twice. */
public class AddPatron {
    public void add(@Val PatronRequest request, @Val Person person, PersonStore people, PatronStore patrons,
            Out<Patron> added) throws InvalidSheetException {
        Person patron = request.patronId() == null ? null : people.find(person.getSheetId(), request.patronId());
        if (patron == null) {
            throw new InvalidSheetException("No such person to be a patron");
        }
        if (patron.getId() == person.getId()) {
            throw new InvalidSheetException("A person cannot be their own patron");
        }
        if (patrons.of(person.getSheetId(), person.getId()).contains(patron.getId())) {
            throw new InvalidSheetException(patron.getName() + " is already a patron");
        }
        patrons.add(person.getSheetId(), person.getId(), patron.getId());
        added.set(new Patron(patron));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePatron {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PatronRequest request, Out<PatronRequest> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(request == null ? new PatronRequest(null, null) : request);
    }
}

