test("aliases scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "terms": "3", "contact": " Ada@x "}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "contact": " Ada@x "})).toBeNull();
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "4.00", "tags": "a"}));
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.defer(pg_uma, c_ben_0, "2026-04-04")).toBe(true);
  expect(await ui.statementAsOf(pg_uma, p_cam, "2026-02-25")).toBe(false);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.defer(pg_uma, c_ben_0, "2026-04-05")).toBe(true);
  await ui.refresh(pg_uma);
  await ui.setSetting(pg_uma, "policy-date", "");
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  expect(await ui.bulkGrade(pg_uma, [p_cam, p_ben], {"grade": "B"})).toBe(2);
  expect(await ui.claimAction(pg_uma, c_ben_0, "void")).toBe(false);
  const c_cam_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "1.00"}, p_cam));
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.unstate(pg_vic, p_cam)).toBe(true);
  expect(await ui.claimAction(pg_vic, c_cam_0, "void")).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.claimAction(pg_vic, c_ben_0, "settle")).toBe(false);
  const c_ben_1 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "10.25", "date": "2026-03-05", "tags": " c "}));
  await ui.refresh(pg_vic);
  expect(await ui.unstate(pg_vic, p_cam)).toBe(true);
  expect(await ui.claimAction(pg_vic, c_ben_1, "void", "error")).toBe(true);
  expect(await ui.claimAction(pg_vic, c_ben_0, "void", "error")).toBe(true);
  expect(await ui.addProof(pg_vic, c_cam_0)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  await ui.refresh(pg_uma);

